import{t as e}from"./api-7M9YWvHU.js";var t={async getPublicOpportunities(t){return(await e.get(`/volunteering/opportunities`,{params:t})).data},async getOpportunityBySlug(t){return(await e.get(`/volunteering/opportunities/${t}`)).data},async submitSignup(t){return(await e.post(`/volunteering/signups`,t)).data},async cancelSignup(t){return(await e.post(`/volunteering/signups/${t}/cancel`)).data},async getMyHistory(){return(await e.get(`/volunteering/my-history`)).data},async getAdminOpportunities(t){return(await e.get(`/admin/volunteering/opportunities`,{params:t})).data},async createOpportunity(t){return(await e.post(`/admin/volunteering/opportunities`,t)).data},async getAdminOpportunity(t){return(await e.get(`/admin/volunteering/opportunities/${t}`)).data},async updateOpportunity(t,n){return(await e.put(`/admin/volunteering/opportunities/${t}`,n)).data},async deleteOpportunity(t){return(await e.delete(`/admin/volunteering/opportunities/${t}`)).data},async getSignupsForOpportunity(t,n){return(await e.get(`/admin/volunteering/opportunities/${t}/signups`,{params:n})).data},async updateSignupStatus(t,n){return(await e.put(`/admin/volunteering/signups/${t}/status`,n)).data},async getAnalytics(){return(await e.get(`/admin/volunteering/analytics`)).data}};export{t};